import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.15 released — Multimodal + MCP + Agent orchestration (AI-LLM 深化)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.15/gh-discussions-announcement.md","filePath":"announcements/v1.15/gh-discussions-announcement.md"}'),s={name:"announcements/v1.15/gh-discussions-announcement.md"};function n(r,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="kiwa-v1-15-released-—-multimodal-mcp-agent-orchestration-ai-llm-深化" tabindex="-1">kiwa v1.15 released — Multimodal + MCP + Agent orchestration (AI-LLM 深化) <a class="header-anchor" href="#kiwa-v1-15-released-—-multimodal-mcp-agent-orchestration-ai-llm-深化" aria-label="Permalink to &quot;kiwa v1.15 released — Multimodal + MCP + Agent orchestration (AI-LLM 深化)&quot;">​</a></h1><p>v1.15 is out. After v1.14&#39;s 横軸拡張 (payment / search / telemetry / Go Iris/Chi), v1.15 pivots back to the <strong>AI-LLM vertical</strong> and covers the three shapes v1.12 did not — multimodal input, Model Context Protocol, and agent orchestration.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-test/ai-llm</code> v0.2</strong> — multimodal (image + audio) input mock across all 4 SDKs (Anthropic Messages API + OpenAI Chat Completions + Vercel AI SDK + LangChain), plus Whisper transcription mock. Image tokens flow into prompt-token accounting; the <code>detail</code> hint scales base cost (0.5× / 0.8× / 1.0× for low / auto / high). Text-only v0.1 tests keep passing.</li><li><strong><code>@kiwa-test/mcp</code> v0.1</strong> — Model Context Protocol server + client mock with <code>InMemoryTransport</code>. Covers the 4 ops MCP-aware tool-use clients need (<code>initialize</code> / <code>notifications/initialized</code> / <code>tools/list</code> / <code>tools/call</code>), 8 JSON-RPC error codes (including MCP extensions -32000 / -32001 / -32002 / -32003), and 5 fixture tools (echo / calc / weather / search / db-query).</li><li><strong><code>@kiwa-test/agent</code> v0.1</strong> — LangGraph-style <code>StateGraph</code> + OpenAI Assistants v2 client under one API. 6-item compile validation (fail-fast), deterministic run ids, run-status transitions (<code>queued</code> → <code>requires_action</code> → <code>submitToolOutputs</code> → <code>completed</code>) match real Assistants v2 shape.</li><li><strong>dogfood-multimodal-chat + dogfood-mcp-tool-agent</strong> — 2 new dogfood apps that measure the mocks against real Anthropic + real MCP endpoints. Both roll into the 11-axis release gate via the <code>@kiwa-test/ai-*</code> provider prefix.</li><li><strong>docs</strong> — 3 new tutorials (multimodal / MCP / agent) + additive migration guide v1.14 → v1.15 + concept doc <code>ai-llm-multimodal-testing.md</code> covering the 6 design decisions behind these mocks. VitePress sidebar refreshed; gh-pages published.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#746-#751)</li><li><strong>6 PRs merged</strong> (#752-#756 + this docs PR)</li><li><strong>3 new / expanded packages</strong> (<code>@kiwa-test/ai-llm</code> v0.2 + <code>@kiwa-test/mcp</code> v0.1 + <code>@kiwa-test/agent</code> v0.1)</li><li><strong>2 new dogfood apps</strong> with fidelity reports feeding the 11-axis gate</li></ul><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Storybook integration (component-level visual regression across the 8-framework matrix)</li><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Framework depth (SolidJS / Fresh / HonoJS)</li></ul><p>Feedback welcome on which of these should land next.</p>',9)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
